import React, {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';

import {
  EyeIcon,
  TrashIcon,
  MagnifyingGlassIcon,
  ArrowPathIcon,
  XMarkIcon,
  UserGroupIcon,
  EnvelopeIcon,
  PhoneIcon,
  BookOpenIcon,
  CalendarDaysIcon,
} from '@heroicons/react/24/outline';

import api, {
  getApiErrorMessage,
} from '../../services/api';


// ==========================================
// STATUS OPTIONS
// ==========================================

const STATUS_OPTIONS = [
  'pending',
  'approved',
  'rejected',
  'completed',
];


// ==========================================
// STATUS STYLE
// ==========================================

const getStatusStyle = (status) => {
  switch (
    String(status || '')
      .toLowerCase()
      .trim()
  ) {
    case 'approved':
      return 'bg-green-100 text-green-700';

    case 'rejected':
      return 'bg-red-100 text-red-700';

    case 'completed':
      return 'bg-blue-100 text-blue-700';

    case 'pending':
    default:
      return 'bg-yellow-100 text-yellow-700';
  }
};


// ==========================================
// FORMAT DATE
// ==========================================

const formatDate = (date) => {
  if (!date) {
    return '-';
  }

  const parsedDate = new Date(date);

  if (Number.isNaN(parsedDate.getTime())) {
    return '-';
  }

  return parsedDate.toLocaleString();
};


// ==========================================
// ADMIN ENROLLMENTS
// ==========================================

const AdminEnrollments = () => {
  const [enrollments, setEnrollments] =
    useState([]);

  const [loading, setLoading] =
    useState(true);

  const [error, setError] =
    useState('');

  const [search, setSearch] =
    useState('');

  const [
    selectedEnrollment,
    setSelectedEnrollment,
  ] = useState(null);

  const [
    deletingId,
    setDeletingId,
  ] = useState(null);

  const [
    updatingId,
    setUpdatingId,
  ] = useState(null);


  // ==========================================
  // FETCH ENROLLMENTS
  // ==========================================

  const fetchEnrollments = useCallback(
    async () => {
      try {
        setLoading(true);
        setError('');

        const response = await api.get(
          '/api/enrollments/'
        );

        const data = response.data;

        if (Array.isArray(data)) {
          setEnrollments(data);
        } else if (
          Array.isArray(data?.items)
        ) {
          setEnrollments(data.items);
        } else {
          setEnrollments([]);
        }

      } catch (err) {
        console.error(
          'Fetch enrollments error:',
          err
        );

        setError(
          getApiErrorMessage(
            err,
            'Failed to load enrollments.'
          )
        );

      } finally {
        setLoading(false);
      }
    },
    []
  );


  // ==========================================
  // LOAD DATA
  // ==========================================

  useEffect(() => {
    fetchEnrollments();
  }, [fetchEnrollments]);


  // ==========================================
  // FILTER / SEARCH
  // ==========================================

  const filteredEnrollments =
    useMemo(() => {
      const keyword = search
        .toLowerCase()
        .trim();

      if (!keyword) {
        return enrollments;
      }

      return enrollments.filter(
        (item) => {
          const values = [
            item.id,
            item.student_name,
            item.student_email,
            item.student_phone,
            item.status,
            item.course_id,
            item.course?.title,
          ];

          return values.some(
            (value) =>
              String(value || '')
                .toLowerCase()
                .includes(keyword)
          );
        }
      );
    }, [enrollments, search]);


  // ==========================================
  // UPDATE STATUS
  // ==========================================

  const handleStatusChange = async (
    enrollment,
    newStatus
  ) => {
    const oldStatus =
      enrollment.status || 'pending';

    if (oldStatus === newStatus) {
      return;
    }

    try {
      setUpdatingId(
        enrollment.id
      );

      setError('');

      const response = await api.patch(
        `/api/enrollments/${enrollment.id}/status`,
        {
          status: newStatus,
        }
      );

      const updatedEnrollment =
        response.data;

      setEnrollments(
        (current) =>
          current.map((item) =>
            item.id === enrollment.id
              ? {
                  ...item,
                  ...updatedEnrollment,
                  status:
                    updatedEnrollment
                      ?.status ||
                    newStatus,
                }
              : item
          )
      );

      setSelectedEnrollment(
        (current) => {
          if (
            !current ||
            current.id !==
              enrollment.id
          ) {
            return current;
          }

          return {
            ...current,
            ...updatedEnrollment,
            status:
              updatedEnrollment?.status ||
              newStatus,
          };
        }
      );

    } catch (err) {
      console.error(
        'Update status error:',
        err
      );

      setError(
        getApiErrorMessage(
          err,
          'Failed to update enrollment status.'
        )
      );

    } finally {
      setUpdatingId(null);
    }
  };


  // ==========================================
  // DELETE ENROLLMENT
  // ==========================================

  const handleDelete = async (
    enrollment
  ) => {
    const confirmed =
      window.confirm(
        `Delete enrollment for "${enrollment.student_name}"?`
      );

    if (!confirmed) {
      return;
    }

    try {
      setDeletingId(
        enrollment.id
      );

      setError('');

      await api.delete(
        `/api/enrollments/${enrollment.id}`
      );

      setEnrollments(
        (current) =>
          current.filter(
            (item) =>
              item.id !==
              enrollment.id
          )
      );

      if (
        selectedEnrollment?.id ===
        enrollment.id
      ) {
        setSelectedEnrollment(null);
      }

    } catch (err) {
      console.error(
        'Delete enrollment error:',
        err
      );

      setError(
        getApiErrorMessage(
          err,
          'Failed to delete enrollment.'
        )
      );

    } finally {
      setDeletingId(null);
    }
  };


  // ==========================================
  // LOADING
  // ==========================================

  if (loading) {
    return (
      <div className="min-h-[400px] flex items-center justify-center">

        <div className="text-center">

          <div className="w-12 h-12 mx-auto rounded-full border-4 border-gray-200 border-t-blue-900 animate-spin" />

          <p className="mt-4 text-gray-500">
            Loading enrollments...
          </p>

        </div>

      </div>
    );
  }


  // ==========================================
  // UI
  // ==========================================

  return (
    <div className="p-4 md:p-6">

      {/* ================================
          HEADER
      ================================= */}

      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 mb-6">

        <div>

          <h1 className="text-2xl font-bold text-gray-900">
            Enrollments
          </h1>

          <p className="text-gray-500 mt-1">
            Manage student course
            enrollments
          </p>

        </div>


        <button
          type="button"
          onClick={
            fetchEnrollments
          }
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-950 text-white rounded-xl hover:bg-blue-900 transition"
        >
          <ArrowPathIcon className="w-5 h-5" />

          Refresh
        </button>

      </div>


      {/* ================================
          ERROR
      ================================= */}

      {error && (
        <div className="mb-5 flex items-start justify-between gap-4 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-xl">

          <span>
            {error}
          </span>

          <button
            type="button"
            onClick={() =>
              setError('')
            }
          >
            <XMarkIcon className="w-5 h-5" />
          </button>

        </div>
      )}


      {/* ================================
          STATS
      ================================= */}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">

        <StatCard
          title="Total"
          value={
            enrollments.length
          }
        />

        <StatCard
          title="Pending"
          value={
            enrollments.filter(
              (item) =>
                item.status ===
                'pending'
            ).length
          }
        />

        <StatCard
          title="Approved"
          value={
            enrollments.filter(
              (item) =>
                item.status ===
                'approved'
            ).length
          }
        />

        <StatCard
          title="Completed"
          value={
            enrollments.filter(
              (item) =>
                item.status ===
                'completed'
            ).length
          }
        />

      </div>


      {/* ================================
          SEARCH
      ================================= */}

      <div className="bg-white border border-gray-200 rounded-2xl p-4 mb-5">

        <div className="relative max-w-md">

          <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />

          <input
            type="text"
            value={search}
            onChange={(e) =>
              setSearch(
                e.target.value
              )
            }
            placeholder="Search student, email, phone, course..."
            className="w-full pl-10 pr-4 py-2.5 border border-gray-300 rounded-xl outline-none focus:ring-2 focus:ring-blue-900/20 focus:border-blue-900"
          />

        </div>

      </div>


      {/* ================================
          TABLE
      ================================= */}

      <div className="bg-white border border-gray-200 rounded-2xl overflow-hidden shadow-sm">

        <div className="overflow-x-auto">

          <table className="w-full min-w-[1000px]">

            <thead className="bg-gray-50 border-b border-gray-200">

              <tr>

                <TableHead>
                  #
                </TableHead>

                <TableHead>
                  Student
                </TableHead>

                <TableHead>
                  Contact
                </TableHead>

                <TableHead>
                  Course
                </TableHead>

                <TableHead>
                  Status
                </TableHead>

                <TableHead>
                  Date
                </TableHead>

                <TableHead>
                  Actions
                </TableHead>

              </tr>

            </thead>


            <tbody className="divide-y divide-gray-100">

              {filteredEnrollments.length ===
              0 ? (

                <tr>

                  <td
                    colSpan="7"
                    className="px-6 py-16 text-center"
                  >

                    <UserGroupIcon className="w-12 h-12 mx-auto text-gray-300 mb-3" />

                    <p className="font-semibold text-gray-700">
                      No enrollments found
                    </p>

                    <p className="text-sm text-gray-400 mt-1">
                      Student enrollments
                      will appear here.
                    </p>

                  </td>

                </tr>

              ) : (

                filteredEnrollments.map(
                  (
                    enrollment,
                    index
                  ) => (

                    <tr
                      key={
                        enrollment.id
                      }
                      className="hover:bg-gray-50/70 transition"
                    >

                      {/* ID */}

                      <td className="px-5 py-4 text-sm text-gray-500">
                        {index + 1}
                      </td>


                      {/* STUDENT */}

                      <td className="px-5 py-4">

                        <div className="font-semibold text-gray-900">
                          {
                            enrollment.student_name
                          }
                        </div>

                        <div className="text-xs text-gray-400 mt-1">
                          ID: {
                            enrollment.id
                          }
                        </div>

                      </td>


                      {/* CONTACT */}

                      <td className="px-5 py-4">

                        <div className="text-sm text-gray-700">
                          {
                            enrollment.student_email
                          }
                        </div>

                        <div className="text-sm text-gray-500 mt-1">
                          {
                            enrollment.student_phone ||
                            '-'
                          }
                        </div>

                      </td>


                      {/* COURSE */}

                      <td className="px-5 py-4">

                        <div className="font-medium text-gray-800">
                          {
                            enrollment.course
                              ?.title ||
                            `Course #${enrollment.course_id}`
                          }
                        </div>

                      </td>


                      {/* STATUS */}

                      <td className="px-5 py-4">

                        <div className="flex flex-col gap-2">

                          <span
                            className={`w-fit px-2.5 py-1 rounded-full text-xs font-semibold capitalize ${getStatusStyle(
                              enrollment.status
                            )}`}
                          >
                            {
                              enrollment.status ||
                              'pending'
                            }
                          </span>

                          <select
                            value={
                              enrollment.status ||
                              'pending'
                            }
                            disabled={
                              updatingId ===
                              enrollment.id
                            }
                            onChange={(e) =>
                              handleStatusChange(
                                enrollment,
                                e.target.value
                              )
                            }
                            className="text-sm border border-gray-300 rounded-lg px-2 py-1.5 outline-none focus:border-blue-900 disabled:opacity-50"
                          >

                            {STATUS_OPTIONS.map(
                              (
                                statusOption
                              ) => (

                                <option
                                  key={
                                    statusOption
                                  }
                                  value={
                                    statusOption
                                  }
                                >
                                  {
                                    statusOption
                                      .charAt(0)
                                      .toUpperCase() +
                                    statusOption.slice(
                                      1
                                    )
                                  }
                                </option>

                              )
                            )}

                          </select>

                        </div>

                      </td>


                      {/* DATE */}

                      <td className="px-5 py-4 text-sm text-gray-600">
                        {formatDate(
                          enrollment.created_at
                        )}
                      </td>


                      {/* ACTIONS */}

                      <td className="px-5 py-4">

                        <div className="flex items-center gap-2">

                          <button
                            type="button"
                            title="View"
                            onClick={() =>
                              setSelectedEnrollment(
                                enrollment
                              )
                            }
                            className="p-2 rounded-lg bg-blue-50 text-blue-700 hover:bg-blue-100 transition"
                          >
                            <EyeIcon className="w-5 h-5" />
                          </button>


                          <button
                            type="button"
                            title="Delete"
                            disabled={
                              deletingId ===
                              enrollment.id
                            }
                            onClick={() =>
                              handleDelete(
                                enrollment
                              )
                            }
                            className="p-2 rounded-lg bg-red-50 text-red-600 hover:bg-red-100 transition disabled:opacity-50"
                          >

                            {deletingId ===
                            enrollment.id ? (

                              <ArrowPathIcon className="w-5 h-5 animate-spin" />

                            ) : (

                              <TrashIcon className="w-5 h-5" />

                            )}

                          </button>

                        </div>

                      </td>

                    </tr>

                  )
                )

              )}

            </tbody>

          </table>

        </div>

      </div>


      {/* ================================
          VIEW MODAL
      ================================= */}

      {selectedEnrollment && (

        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">

          <div className="bg-white w-full max-w-2xl rounded-2xl shadow-xl max-h-[90vh] overflow-y-auto">

            {/* Modal Header */}

            <div className="flex items-center justify-between px-6 py-5 border-b border-gray-200">

              <div>

                <h2 className="text-xl font-bold text-gray-900">
                  Enrollment Details
                </h2>

                <p className="text-sm text-gray-500 mt-1">
                  Enrollment #
                  {
                    selectedEnrollment.id
                  }
                </p>

              </div>


              <button
                type="button"
                onClick={() =>
                  setSelectedEnrollment(
                    null
                  )
                }
                className="p-2 rounded-lg hover:bg-gray-100"
              >
                <XMarkIcon className="w-6 h-6" />
              </button>

            </div>


            {/* Modal Body */}

            <div className="p-6 space-y-5">

              <DetailItem
                icon={UserGroupIcon}
                label="Student Name"
                value={
                  selectedEnrollment.student_name
                }
              />

              <DetailItem
                icon={EnvelopeIcon}
                label="Email"
                value={
                  selectedEnrollment.student_email
                }
              />

              <DetailItem
                icon={PhoneIcon}
                label="Phone"
                value={
                  selectedEnrollment.student_phone ||
                  '-'
                }
              />

              <DetailItem
                icon={BookOpenIcon}
                label="Course"
                value={
                  selectedEnrollment.course
                    ?.title ||
                  `Course #${selectedEnrollment.course_id}`
                }
              />

              <DetailItem
                icon={CalendarDaysIcon}
                label="Enrollment Date"
                value={formatDate(
                  selectedEnrollment.created_at
                )}
              />


              {/* Status */}

              <div>

                <label className="block text-sm font-semibold text-gray-500 mb-2">
                  Status
                </label>

                <select
                  value={
                    selectedEnrollment.status ||
                    'pending'
                  }
                  disabled={
                    updatingId ===
                    selectedEnrollment.id
                  }
                  onChange={(e) =>
                    handleStatusChange(
                      selectedEnrollment,
                      e.target.value
                    )
                  }
                  className="w-full border border-gray-300 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-900/20 focus:border-blue-900"
                >

                  {STATUS_OPTIONS.map(
                    (statusOption) => (

                      <option
                        key={
                          statusOption
                        }
                        value={
                          statusOption
                        }
                      >
                        {
                          statusOption
                            .charAt(0)
                            .toUpperCase() +
                          statusOption.slice(
                            1
                          )
                        }
                      </option>

                    )
                  )}

                </select>

              </div>


              {/* Message */}

              <div>

                <label className="block text-sm font-semibold text-gray-500 mb-2">
                  Message
                </label>

                <div className="bg-gray-50 border border-gray-200 rounded-xl p-4 text-gray-700 whitespace-pre-wrap min-h-[100px]">

                  {
                    selectedEnrollment.message ||
                    'No message provided.'
                  }

                </div>

              </div>

            </div>


            {/* Modal Footer */}

            <div className="flex justify-end gap-3 px-6 py-4 border-t border-gray-200">

              <button
                type="button"
                onClick={() =>
                  setSelectedEnrollment(
                    null
                  )
                }
                className="px-5 py-2.5 border border-gray-300 rounded-xl text-gray-700 hover:bg-gray-50"
              >
                Close
              </button>

              <button
                type="button"
                onClick={() =>
                  handleDelete(
                    selectedEnrollment
                  )
                }
                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700"
              >
                Delete
              </button>

            </div>

          </div>

        </div>

      )}

    </div>
  );
};


// ==========================================
// STAT CARD
// ==========================================

const StatCard = ({
  title,
  value,
}) => {
  return (
    <div className="bg-white border border-gray-200 rounded-2xl p-5 shadow-sm">

      <p className="text-sm font-medium text-gray-500">
        {title}
      </p>

      <p className="text-3xl font-bold text-gray-900 mt-2">
        {value}
      </p>

    </div>
  );
};


// ==========================================
// TABLE HEAD
// ==========================================

const TableHead = ({
  children,
}) => {
  return (
    <th className="px-5 py-4 text-left text-xs font-bold uppercase tracking-wider text-gray-500">
      {children}
    </th>
  );
};


// ==========================================
// DETAIL ITEM
// ==========================================

const DetailItem = ({
  icon: Icon,
  label,
  value,
}) => {
  return (
    <div className="flex items-start gap-4">

      <div className="w-10 h-10 rounded-xl bg-blue-50 flex items-center justify-center flex-shrink-0">

        <Icon className="w-5 h-5 text-blue-900" />

      </div>

      <div>

        <p className="text-sm font-medium text-gray-500">
          {label}
        </p>

        <p className="text-gray-900 font-medium mt-1">
          {value || '-'}
        </p>

      </div>

    </div>
  );
};


export default AdminEnrollments;
